const moduleReadiness=$json;
const input=$('Receive Delivery Context').item.json;
const eventId=input.customer_event_id;
const trigger=String(input.trigger_type ?? '');
const delivery=input.existing_delivery ?? null;
const lookup=input.onedrive_lookup ?? null;

if(trigger==='event_completed'){
  if(delivery && ['sent','confirmed'].includes(delivery.status)){
    return {json:{
      status:'no_action',
      module_readiness:moduleReadiness,
      operations:[],
      blockers:[]
    }};
  }
  return {json:{
    status:'adapter_required',
    module_readiness:moduleReadiness,
    operations:[
      {
        action:'UPSERT_DELIVERY',
        idempotency_key:'delivery:onedrive:'+String(eventId),
        customer_event_id:eventId,
        provider:'onedrive',
        delivery_kind:'original_media',
        status:'pending'
      },
      {
        action:'UPSERT_MODULE_STATE',
        customer_event_id:eventId,
        module_code:'delivery',
        status:'in_progress',
        ready:false,
        blockers:['ONEDRIVE_LINK_PENDING']
      },
      {
        action:'REQUEST_ONEDRIVE_LOOKUP',
        idempotency_key:'onedrive-lookup:'+String(eventId),
        customer_event_id:eventId
      }
    ],
    blockers:['ONEDRIVE_ADAPTER_NOT_CONNECTED']
  }};
}

if(trigger==='onedrive_lookup'){
  const found=lookup?.status==='found' &&
    lookup?.provider==='onedrive' &&
    Boolean(lookup?.folder_ref) &&
    Boolean(lookup?.share_url);

  if(!found){
    return {json:{
      status:'pending_human',
      module_readiness:moduleReadiness,
      operations:[
        {
          action:'UPSERT_DELIVERY',
          idempotency_key:'delivery:onedrive:'+String(eventId),
          customer_event_id:eventId,
          provider:'onedrive',
          delivery_kind:'original_media',
          status:'pending',
          folder_ref:lookup?.folder_ref ?? null,
          share_url:null
        },
        {
          action:'CREATE_HUMAN_TASK',
          customer_event_id:eventId,
          task_type:'delivery_missing_onedrive',
          reason_code:'ONEDRIVE_LINK_NOT_FOUND'
        },
        {
          action:'UPSERT_MODULE_STATE',
          customer_event_id:eventId,
          module_code:'delivery',
          status:'in_progress',
          ready:false,
          blockers:['ONEDRIVE_LINK_NOT_FOUND']
        }
      ],
      blockers:['ONEDRIVE_LINK_NOT_FOUND']
    }};
  }

  return {json:{
    status:'ready_shadow',
    module_readiness:moduleReadiness,
    operations:[
      {
        action:'UPSERT_DELIVERY',
        idempotency_key:'delivery:onedrive:'+String(eventId),
        customer_event_id:eventId,
        provider:'onedrive',
        delivery_kind:'original_media',
        status:'ready',
        folder_ref:lookup.folder_ref,
        share_url:lookup.share_url
      },
      {action:'EMIT_EVENT',event_type:'delivery_ready',customer_event_id:eventId},
      {
        action:'REQUEST_RESPONSE_COMPOSITION',
        customer_event_id:eventId,
        response_action:'COMPOSE_DELIVERY_LINK',
        delivery_link:lookup.share_url,
        delivery_provider:'onedrive'
      }
    ],
    blockers:['SEND_DISABLED']
  }};
}

if(trigger==='dispatch_success'){
  if(!delivery || delivery.status!=='ready' || !delivery.share_url){
    return {json:{status:'blocked',module_readiness:moduleReadiness,operations:[],blockers:['DELIVERY_NOT_READY_FOR_SENT']}};
  }
  if(String(input.dispatched_share_url ?? '')!==String(delivery.share_url)){
    return {json:{status:'blocked',module_readiness:moduleReadiness,operations:[],blockers:['DELIVERY_LINK_MISMATCH']}};
  }
  return {json:{
    status:'sent',
    module_readiness:{status:'in_progress',ready:false,blockers:['DELIVERY_POLICY_INCOMPLETE']},
    operations:[
      {action:'UPDATE_DELIVERY_STATUS',delivery_id:delivery.id ?? null,from_status:'ready',to_status:'sent',sent_at:'NOW'},
      {action:'EMIT_EVENT',event_type:'delivery_link_sent',customer_event_id:eventId,delivery_id:delivery.id ?? null},
      {action:'UPSERT_MODULE_STATE',customer_event_id:eventId,module_code:'delivery',status:'in_progress',ready:false,blockers:['DELIVERY_CONFIRMATION_PENDING']}
    ],
    blockers:[]
  }};
}

if(trigger==='customer_confirmation'){
  if(!delivery || !['sent','confirmed'].includes(delivery.status)){
    return {json:{status:'blocked',module_readiness:moduleReadiness,operations:[],blockers:['DELIVERY_NOT_SENT']}};
  }
  if(delivery.status==='confirmed'){
    return {json:{status:'no_action',module_readiness:{status:'completed',ready:true,blockers:[]},operations:[],blockers:[]}};
  }
  return {json:{
    status:'confirmed',
    module_readiness:{status:'completed',ready:true,blockers:[]},
    operations:[
      {action:'UPDATE_DELIVERY_STATUS',delivery_id:delivery.id ?? null,from_status:'sent',to_status:'confirmed',confirmed_at:'NOW'},
      {action:'EMIT_EVENT',event_type:'delivery_confirmed',customer_event_id:eventId,delivery_id:delivery.id ?? null},
      {action:'UPSERT_MODULE_STATE',customer_event_id:eventId,module_code:'delivery',status:'completed',ready:true,blockers:[]}
    ],
    blockers:[]
  }};
}

return {json:{status:'blocked',module_readiness:moduleReadiness,operations:[],blockers:['DELIVERY_TRIGGER_UNKNOWN']}};
